sec_re=re.compile(r'^\s*(\d{1,2}\.\d{1,2})\s+([A-Za-z][^\d]*?)(?:\s+(?:Maximum|Points).*)?$')
crit_re=re.compile(r'^\s*(\d{1,2}\.\d{1,2}[A-Z]?\.\d{1,2})\s+(.*?)\s+(\d{1,2}|Yes/No)\s*$')
crit_nopts=re.compile(r'^\s*(\d{1,2}\.\d{1,2}[A-Z]?\.\d{1,2})\s+(.*)$')
for ln in L:
    s=ln.strip()
    if not s or s.startswith('—') or s in ('Maximum','Points') or s.startswith('Total'): 
