    m=crit_re.match(s)
    if m:
        cur={'code':m.group(1),'text':m.group(2).strip(),'points':m.group(3),'section':m.group(1).rsplit('.',1)[0]}
        rows.append(cur); continue
    m=crit_nopts.match(s)
    if m and re.match(r'^\d{1,2}\.\d{1,2}[A-Z]?\.\d{1,2}$',m.group(1)):
        cur={'code':m.group(1),'text':m.group(2).strip(),'points':None,'section':m.group(1).rsplit('.',1)[0]}
        rows.append(cur); continue
    # continuation line of previous criterion: ends possibly with points
    if cur is not None and not re.match(r'^\d{1,2}\.\d{1,2}\s',s) and not re.match(r'^\d{1,2}\.\s',s):
        mm=re.match(r'^(.*?)\s+(\d{1,2})$',s)
        if mm and cur['points'] is None:
            cur['text']+=' '+mm.group(1); cur['points']=mm.group(2)
        else:
            cur['text']+=' '+s
json.dump(rows,open(f'{SCR}/rhfac_rows_raw.json','w'),ensure_ascii=False,indent=0)
print(len(rows)); 
import collections
nopts=[r for r in rows if r['points'] is None]; print('no points',len(nopts)); 
for r in nopts[:12]: print(r)
c=collections.Counter(r['section'].split('.')[0] for r in rows); print(sorted(c.items(), key=lambda x:int(x[0])))
